   117	export function resolveManagedReviewerBasePrompt(root: string, run: ReviewRun): string {
   118	  if (run.assembledPrompt) return run.assembledPrompt;
   119	  // A no-envelope ReviewRun predates modular prompt assembly. Its signed
   120	  // promptHash therefore names the frozen legacy role body, regardless of a
   121	  // later rollout/template-mode change in the live project configuration.
   122	  // Reconstructing through that current mode turns valid historical evidence
   123	  // into apparent prompt drift; current envelope runs keep their strict exact
   124	  // assembled-prompt verification above.
   125	  const body = resolvePromptRoleBody(run.lane, {
   126	    version: PROMPT_ENVELOPE_ROLLOUT_VERSION,
   127	    roles: { [run.lane]: 'legacy-full-context' },
   128	  }).body;
