   171	      `finding_add: evidenceState must be one of ${FINDING_EVIDENCE_STATES.join('|')}`,
   172	    );
   173	  }
   174	  if (raw === 'suspected') {
   175	    const reason = (args.uncertaintyReason ?? '').trim();
   176	    if (reason.length < 10) {
   177	      throw new Error(
   178	        'finding_add: evidenceState=suspected must include uncertaintyReason (≥10 characters), ' +
   179	        'explaining why it is merely suspected (not reproduced / lacking source evidence), to prevent using suspected as a button to bypass the gate',
   180	      );
   181	    }
   182	    return { evidenceState: 'suspected', uncertaintyReason: reason };
   183	  }
   184	  if (raw === 'disproven') {
