   186	    if (summary.length < 10) {
   187	      throw new Error(
   188	        'finding_add: evidenceState=disproven must include disprovenEvidence.summary (≥10 characters), ' +
   189	        'recording the counter-evidence summary; may attach sourceRefs / reproCommand',
   190	      );
   191	    }
   192	    const sourceRefs = args.disprovenEvidence?.sourceRefs?.filter(r => r.trim().length > 0);
   193	    const reproCommand = args.disprovenEvidence?.reproCommand?.trim();
   194	    return {
   195	      evidenceState: 'disproven',
   196	      disprovenEvidence: {
