   312	export function readGapLogProvenanceLedger(root: string): GapLogProvenanceReceipt[] {
   313	  const path = join(root, GAP_LOG_PROVENANCE_LEDGER_PATH);
   314	  if (!existsSync(path)) return [];
   315	  return readFileSync(path, 'utf8')
   316	    .split('\n')
   317	    .filter(Boolean)
   318	    .map((line) => JSON.parse(line) as GapLogProvenanceReceipt);
   319	}
