   321	export interface GapLogArtifactVerification {
   322	  trusted: boolean;
   323	  reason:
   324	    | 'valid_official_gap_log_binding'
   325	    | 'wrong_artifact_path'
   326	    | 'missing_binding'
   327	    | 'invalid_binding_shape'
   328	    | 'content_digest_mismatch'
   329	    | 'finding_signature_invalid';
   330	  expectedDigest?: string;
   331	  observedDigest?: string;
   332	  findingId?: string;
   333	}
   334	
   335	export function verifyGapLogArtifactBinding(
   336	  data: FindingData,
   337	  artifactPath: string = GAP_LOG_ARTIFACT_PATH,
   338	  projectRoot?: string,
   339	  gitCwdOverride?: string,
   340	): GapLogArtifactVerification {
   341	  if (artifactPath.replace(/\\/g, '/').replace(/^\.\//, '') !== GAP_LOG_ARTIFACT_PATH) {
   342	    return { trusted: false, reason: 'wrong_artifact_path' };
   343	  }
   344	  if (!projectRoot || !gitCwdOverride) return { trusted: false, reason: 'missing_binding' };
   345	  const gitCwd = gitCwdOverride;
   346	  let receipts: GapLogProvenanceReceipt[];
   347	  try {
   348	    receipts = readGapLogProvenanceLedger(projectRoot);
   349	  } catch {
   350	    return { trusted: false, reason: 'invalid_binding_shape' };
   351	  }
   352	  if (receipts.length === 0) return { trusted: false, reason: 'missing_binding' };
   353	  let previous = '';
   354	  let priorPost = receipts[0].preArtifactDigest;
   355	  const firstCommittedDigest = committedArtifactDigest(gitCwd, receipts[0].parentHead);
   356	  const canonicalEmptyDigest = digestGapLogArtifact({ findings: [] });
   357	  if (
   358	    (firstCommittedDigest !== null && firstCommittedDigest !== receipts[0].preArtifactDigest)
   359	    || (firstCommittedDigest === null && receipts[0].preArtifactDigest !== canonicalEmptyDigest)
   360	  ) {
   361	    return { trusted: false, reason: 'invalid_binding_shape', findingId: receipts[0].findingId };
   362	  }
   363	  for (let index = 0; index < receipts.length; index++) {
   364	    const receipt = receipts[index];
   365	    const { integrityHash, ...unsigned } = receipt;
   366	    const expected = expectedReceiptHash(gitCwd, unsigned);
   367	    const authentic = expected && /^[a-f0-9]{64}$/.test(integrityHash)
   368	      && timingSafeEqual(Buffer.from(expected, 'hex'), Buffer.from(integrityHash, 'hex'));
   369	    if (
   370	      !authentic
   371	      || receipt.schemaVersion !== GAP_LOG_PROVENANCE_SCHEMA
   372	      || receipt.sequence !== index + 1
   373	      || receipt.previousIntegrityHash !== previous
   374	      || receipt.preArtifactDigest !== priorPost
   375	      || receipt.artifactPath !== GAP_LOG_ARTIFACT_PATH
   376	      || receipt.ledgerPath !== GAP_LOG_PROVENANCE_LEDGER_PATH
   377	      || receipt.storyId !== 'B-META-framework-audit'
   378	      || receipt.writerCommand !== 'gap_log'
   379	      || !/^[a-f0-9]{40,64}$/.test(receipt.parentHead)
   380	      || !Number.isFinite(Date.parse(receipt.timestamp))
   381	    ) return { trusted: false, reason: 'invalid_binding_shape', findingId: receipt.findingId };
   382	    previous = integrityHash;
   383	    priorPost = receipt.postArtifactDigest;
   384	  }
   385	  const latest = receipts[receipts.length - 1];
   386	  const expectedDigest = digestGapLogArtifact(data);
   387	  if (latest.postArtifactDigest !== expectedDigest) {
   388	    return {
   389	      trusted: false,
   390	      reason: 'content_digest_mismatch',
   391	      expectedDigest,
   392	      observedDigest: latest.postArtifactDigest,
   393	      findingId: latest.findingId,
   394	    };
   395	  }
   396	  const finding = data.findings.find((candidate) => candidate.id === latest.findingId);
   397	  if (!finding || finding.gapFingerprint !== latest.gapFingerprint) {
   398	    return { trusted: false, reason: 'finding_signature_invalid', expectedDigest, observedDigest: latest.postArtifactDigest, findingId: latest.findingId };
   399	  }
   400	  return {
   401	    trusted: true,
   402	    reason: 'valid_official_gap_log_binding',
   403	    expectedDigest,
   404	    observedDigest: latest.postArtifactDigest,
   405	    findingId: latest.findingId,
   406	  };
   407	}
